package com.brasa.restaurant.model;import com.brasa.restaurant.enums.Enums.StatusPedido;import jakarta.persistence.*;import java.math.BigDecimal;import java.util.*;@Entity@Table(name="pedidos")public class Pedido extends BaseEntity{@Column(name="restaurante_id",nullable=false)private String restauranteId;private int numeroMesa;private String nomeCliente;@Enumerated(EnumType.STRING)private StatusPedido status=StatusPedido.PENDENTE;private BigDecimal total=BigDecimal.ZERO;@OneToMany(mappedBy="pedido",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)private List<ItemPedido>itens=new ArrayList<>();public void addItem(ItemPedido i){i.setPedido(this);itens.add(i);}public String getRestauranteId(){return restauranteId;}public void setRestauranteId(String v){restauranteId=v;}public int getNumeroMesa(){return numeroMesa;}public void setNumeroMesa(int v){numeroMesa=v;}public String getNomeCliente(){return nomeCliente;}public void setNomeCliente(String v){nomeCliente=v;}public StatusPedido getStatus(){return status;}public void setStatus(StatusPedido v){status=v;}public BigDecimal getTotal(){return total;}public void setTotal(BigDecimal v){total=v;}public List<ItemPedido>getItens(){return itens;}}
